    const T = [
      ['c41e88a09d3b7f12', '2026-10-27 14:27:03', 'frontend', 'GET /product/66VCHSJNUP', 1020, 7, true],
      ['2b9d0e7c55a1f3e4', '2026-10-27 14:25:40', 'frontend', 'GET /', 612, 14, false],
      ['7f3a9c2e41b0d6a8', '2026-10-27 14:24:12', 'frontend', 'GET /product/OLJCESPC7Z', 486, 7, false],
      ['9a07d2f6e8c4b310', '2026-10-27 14:29:51', 'frontend', 'POST /cart', 402, 9, false],
      ['e5c1a0d9b7f24c63', '2026-10-27 14:30:18', 'frontend', 'GET /product/1YMWWN1N4O', 377, 7, false],
      ['3d8b6f1c0a9e2d75', '2026-10-27 14:23:02', 'frontend', 'GET /product/L9ECAV7KIM', 341, 7, false],
      ['a1f4c7e2b8d03965', '2026-10-27 14:28:44', 'frontend', 'GET /product/2ZYFJ3GM2N', 318, 7, false],
      ['6b2e9d4a1c7f8e03', '2026-10-27 14:31:09', 'frontend', 'GET /product/0PUK6V6EV0', 297, 7, false]
    ];
    const fmt = (ms) => ms >= 1000 ? (ms / 1000).toFixed(2) + ' s' : Math.round(ms) + ' ms';
    const sel = this.state.sel;
    const traces = T.map(([id, start, svc, name, dur, spans, err], i) => ({ id, start, svc, name, dur: fmt(dur), spans: String(spans), on: i === sel ? 'true' : 'false',
      pick: () => this.setState({ sel: i, open: 3 }),
      durStyle: 'padding: 0 16px; text-align: right; font-variant-numeric: tabular-nums; ' + (err ? 'color: var(--error-text)' : ''),
      row: 'display: grid; grid-template-columns: 180px 180px 160px minmax(0, 1fr) 100px 80px; height: 44px; align-items: center; ' + (i < T.length - 1 ? 'border-bottom: 1px solid var(--border-weak); ' : '') + (i === sel ? 'background: var(--selected)' : '') }));
    const t = T[sel];
