    const netGap = slow - 12;
    const pid = (s) => s === 'frontend' ? 'frontend-6f9c8d7b4-q7lzt' : (s === 'currencyservice' ? 'currencyservice-5d7b9c6f8-hv2rn' : 'productcatalogservice-7c9d8f6b5-x2kq4');
