    const err = ser(3, 0.3, 0.3, 3.5, 1.5).map((v) => hide.error ? 0 : Math.max(0, v));
    const base2 = info.map((v, i) => v + warn[i]);
    const vol = { info: bars(info, 60, 120), warn: bars(warn, 60, 120, info), err: bars(err, 60, 120, base2) };
