    const tab = this.state.tab ?? Math.max(0, T.indexOf(this.props.tab ?? '일반'));
    const tabs = T.map((label, i) => ({ label, sel: tab === i ? 'true' : 'false', pick: () => this.setState({ tab: i, ds: null }),
      style: 'height: 40px; padding: 0; border: 0; background: none; white-space: nowrap; ' + (tab === i ? 'color: var(--text); font-weight: 500; box-shadow: inset 0 -2px 0 var(--text)' : 'color: var(--text-2)') }));
    const pref = this.state.pref;
    const themeOpts = [['light', '라이트'], ['dark', '다크'], ['system', '시스템']].map(([k, label]) => ({ label, sel: pref === k ? 'true' : 'false',
      pick: () => this.setState({ pref: k, theme: k === 'system' ? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : k }),
      style: 'height: 28px; padding: 0 14px; border: 0; border-radius: 6px; ' + (pref === k ? 'background: var(--bg1); box-shadow: var(--shadow-z1); font-weight: 500; color: var(--text)' : 'background: transparent; color: var(--text-2)') }));
    const logo = (c) => 'width: 32px; height: 32px; flex: none; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 600; color: var(--text); background: var(--bg2); border: 1px solid var(--border-weak)';
    const D = [
      { id: 'prom', name: 'Prometheus', type: 'Prometheus', url: 'http://prometheus.monitoring:9090', c: '--viz-orange', isDefault: true },
      { id: 'tempo', name: 'Tempo', type: 'Tempo', url: 'http://tempo.monitoring:3200', c: '--viz-blue', isDefault: false },
      { id: 'loki', name: 'Loki', type: 'Loki', url: 'http://loki.monitoring:3100', c: '--viz-yellow', isDefault: false }
    ];
    const tests = this.state.tests;
    const sources = D.map((d) => {
      const t = tests[d.id];
      const bad = d.id === 'loki' && t !== 'ok';
      return { ...d, initial: d.name[0], logo: logo(d.c), open: () => this.setState({ ds: d.id }),
        status: bad ? '수집 끊김' : '연결됨',
        row: 'display: flex; align-items: center; gap: 16px; width: 100%; padding: 12px 20px; border: 0; background: none; text-align: left; ' + (d.id !== 'loki' ? 'border-bottom: 1px solid var(--border-weak)' : ''),
        statusStyle: 'flex: none; display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: 6px; font-size: 12px; font-weight: 500; white-space: nowrap; ' + (bad ? 'color: var(--error-text); background: color-mix(in srgb, var(--error) 10%, var(--bg1))' : 'color: var(--text-2); background: var(--secondary)') };
    });
    const curD = sources.find((s) => s.id === this.state.ds) || sources[0];
    const curTest = tests[curD.id];
    const C = [
      { name: 'sre-alerts', type: 'Slack', target: '#sre-alerts', last: '마지막 전송 14:22:00' },
      { name: 'oncall-email', type: '이메일', target: 'oncall@example.ac.kr', last: '마지막 전송 13:12:40' },
      { name: 'lab-webhook', type: 'Webhook', target: 'https://hooks.example.ac.kr/sentrix', last: '전송 기록 없음' }
    ];
